const toggle=document.getElementById("nav-toggle"),mobile=document.getElementById("nav-mobile");toggle&&mobile&&(toggle.addEventListener("click",()=>{const e=mobile.classList.toggle("hidden")===!1;toggle.setAttribute("aria-expanded",String(e))}),mobile.querySelectorAll("a").forEach(e=>e.addEventListener("click",()=>{mobile.classList.add("hidden"),toggle.setAttribute("aria-expanded","false")})))